(** The module, decoded. *)
Definition malloc_module : module := Eval vm_compute in
  code_module malloc_term.

(** The term decodes to the module. *)
Lemma malloc_decodes : decode_module malloc_term = Some malloc_module.
Proof. vm_compute. reflexivity. Qed.

(** The function named n of the module, or an empty one. *)
Definition malloc_fn (n : string) : func :=
  code_function malloc_module n.

(** glibc's `__GI___libc_malloc`. *)
Definition glibc_libc_malloc : func := Eval vm_compute in malloc_fn "__GI___libc_malloc".
(** The module defines `__GI___libc_malloc` as [glibc_libc_malloc]. *)
Lemma glibc_libc_malloc_found : find_direct (TAtom "__GI___libc_malloc") malloc_module = Some (Defined glibc_libc_malloc).
Proof. vm_compute. reflexivity. Qed.

